<script>
  // @ts-nocheck
  import { onMount } from 'svelte'; import BotonVolver from '$lib/componentes/BotonVolver.svelte'; import { pedirApi } from '$lib/api.js'; import { fmtPesos } from '$lib/formato.js';
  let datos=$state(null); let error=$state(''); onMount(async()=>{try{datos=await pedirApi('/api/resumen')}catch(e){error=e.message}});
  const maxTop=$derived(datos ? Math.max(1,...datos.top_productos.map(p=>p.cantidad)) : 1); const maxSemana=$derived(datos ? Math.max(1,...datos.semana.map(p=>p.total)) : 1);
</script>
<BotonVolver /><h2>Resumen</h2><p class="text-muted">Una vista rápida del negocio.</p>{#if error}<p class="error">{error}</p>{/if}{#if datos}<div class="stats"><div class="card"><span class="card-kicker">Hoy</span><strong>{fmtPesos(datos.hoy.total)}</strong></div><div class="card"><span class="card-kicker">Tickets</span><strong>{datos.hoy.cantidad}</strong></div><div class="card"><span class="card-kicker">Promedio</span><strong>{fmtPesos(datos.hoy.promedio)}</strong></div><div class="card"><span class="card-kicker">Para reponer</span><strong>{datos.alertas}</strong></div></div><div class="paneles"><section class="card"><h4>Más vendidos</h4>{#each datos.top_productos as p}<div class="barra"><span>{p.descripcion}</span><i style={`width:${p.cantidad / maxTop * 100}%`}></i><small>{p.cantidad}</small></div>{/each}</section><section class="card"><h4>Últimos 7 días</h4><div class="semana">{#each datos.semana as d}<div><i style={`height:${d.total / maxSemana * 100}%`}></i><small>{d.fecha.slice(5)}</small></div>{/each}</div></section></div>{/if}
<style>.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:18px 0}.stats strong{font-size:21px}.paneles{display:grid;grid-template-columns:1fr 1fr;gap:16px}.barra{display:grid;grid-template-columns:1fr 2fr 34px;gap:8px;align-items:center;margin:9px 0}.barra i,.semana i{display:block;background:var(--color-accent);min-height:7px;border-radius:4px}.semana{height:170px;display:flex;gap:8px;align-items:end}.semana div{height:100%;flex:1;display:flex;flex-direction:column;justify-content:end;align-items:center;gap:5px}.semana i{width:100%;background:var(--color-accent-300)}.error{color:var(--color-peligro)}</style>
